import sqlite3
import json

conn = sqlite3.connect('/workspace/world.db')
conn.row_factory = sqlite3.Row

# Comprehensive fix for ALL tau2Airline flights
cursor = conn.execute("SELECT flight_id, cabin_prices_json, dates_json, departure_time, arrival_time FROM flights WHERE source_skill='tau2Airline'")
rows = cursor.fetchall()

fixes = 0
for row in rows:
    fid = row['flight_id']
    updates = {}

    # Fix NULL times
    if not row['departure_time'] or row['departure_time'] == '':
        updates['departure_time'] = '08:00:00'
    if not row['arrival_time'] or row['arrival_time'] == '':
        updates['arrival_time'] = '12:00:00'

    # Fix cabin_prices_json
    cp = json.loads(row['cabin_prices_json'] or '{}')
    cp_changed = False
    for bad_key in list(cp.keys()):
        if bad_key not in ('economy', 'business', 'basic_economy'):
            if bad_key in ('first', 'first_class'):
                if 'business' not in cp:
                    cp['business'] = cp.pop(bad_key)
                else:
                    del cp[bad_key]
            elif bad_key in ('premium_economy', 'premium'):
                if 'economy' not in cp:
                    cp['economy'] = cp.pop(bad_key)
                else:
                    del cp[bad_key]
            else:
                del cp[bad_key]
            cp_changed = True
    if cp_changed:
        updates['cabin_prices_json'] = json.dumps(cp)

    # Fix dates_json prices
    dj = json.loads(row['dates_json'] or '{}')
    dj_changed = False
    for date_key, date_val in dj.items():
        if isinstance(date_val, dict):
            prices = date_val.get('prices', {})
            for bad_key in list(prices.keys()):
                if bad_key not in ('economy', 'business', 'basic_economy'):
                    if bad_key in ('first', 'first_class'):
                        if 'business' not in prices:
                            prices['business'] = prices.pop(bad_key)
                        else:
                            del prices[bad_key]
                    elif bad_key in ('premium_economy', 'premium'):
                        if 'economy' not in prices:
                            prices['economy'] = prices.pop(bad_key)
                        else:
                            del prices[bad_key]
                    else:
                        del prices[bad_key]
                    dj_changed = True
            # Also fix available_seats if present
            seats = date_val.get('available_seats', {})
            for bad_key in list(seats.keys()):
                if bad_key not in ('economy', 'business', 'basic_economy'):
                    if bad_key in ('first', 'first_class'):
                        if 'business' not in seats:
                            seats['business'] = seats.pop(bad_key)
                        else:
                            del seats[bad_key]
                    elif bad_key in ('premium_economy', 'premium'):
                        if 'economy' not in seats:
                            seats['economy'] = seats.pop(bad_key)
                        else:
                            del seats[bad_key]
                    else:
                        del seats[bad_key]
                    dj_changed = True
    if dj_changed:
        updates['dates_json'] = json.dumps(dj)

    if updates:
        set_clause = ', '.join(f"{k}=?" for k in updates)
        vals = list(updates.values()) + [fid]
        conn.execute(f"UPDATE flights SET {set_clause} WHERE flight_id=?", vals)
        fixes += 1

conn.commit()
print(f"Fixes applied to {fixes} flights")

# Verify
issues = []
cursor2 = conn.execute("SELECT flight_id, cabin_prices_json, dates_json, departure_time, arrival_time FROM flights WHERE source_skill='tau2Airline'")
for row in cursor2.fetchall():
    cp = json.loads(row['cabin_prices_json'] or '{}')
