            for sk in dv.get('available_seats', {}):
                if sk not in ('economy', 'business', 'basic_economy'):
                    issues.append(f"{row['flight_id']}/{dk}: bad seat key {sk}")

print(f"Remaining issues: {len(issues)}")
for i in issues[:5]:
    print(f"  {i}")

conn.close()
